import { useState, useEffect } from 'react';
import product from '../../product';
import styles from './payment.module.css';

const Payment = () => {
  const [userName, setUserName] = useState('');
  const [numberTelephone, setNumberTelephone] = useState('');
  const [email, setEmail] = useState('');
  const [errors, setErrors] = useState({
    name: '',
    phone: '',
  });

  // Автоматическое скрытие ошибок
  useEffect(() => {
    const timer = setTimeout(() => {
      setErrors({ name: '', phone: '' });
    }, 2000);
    return () => clearTimeout(timer);
  }, [errors.name, errors.phone]);

  const handleUserNameChange = (e) => {
    const value = e.target.value;
    // Проверка на кириллицу/латиницу (можно заменить на /^[a-zA-Z]+$/ если только латиница)
    const lettersOnly = /^[a-zA-Zа-яА-ЯёЁ\s-]*$/;

    if (lettersOnly.test(value)) {
      setUserName(value);
      setError('');
    } else {
      setError('Имя может содержать только буквы');
    }
  };

  const handleNumberTelephoneChange = (e) => {
    const value = e.target.value;
    // Проверка на кириллицу/латиницу (можно заменить на /^[a-zA-Z]+$/ если только латиница)
    const lettersOnly = /^[0-9+]*$/;

    if (lettersOnly.test(value)) {
      setNumberTelephone(value);
      setError('');
    } else {
      setError(`Номер телефона может содержать только цифры и знак '+'`);
    }
  };

  //получаем данные из sessionStorage
  let cartIds = JSON.parse(sessionStorage.getItem('cartIds')) || [];
  // console.log('basket', cartIds);

  const totalPrice = sessionStorage.getItem('totalPrice'); // Получаем цену
  // console.log(totalPrice);

  //фильтруем и узнаем что лежит в корзине
  const basket = product
    .filter((item) => cartIds.includes(item.id))
    .map((item) => ({ id: item.id, title: item.title }));

  // console.log(basket);

  return (
    <div className={styles.payment}>
      <h1 className={styles.title}>Оформление заказа</h1>

      <div className={styles.container}>
        {/* Форма */}
        <div className={styles.form}>
          <h2 className={styles.subtitle}>Контактные данные</h2>
          <form>
            <input
              type="text"
              placeholder="Ваше имя"
              value={userName}
              required
              onChange={handleUserNameChange}
              className={styles.input}
            />
            {error && <p className={styles.error}>{error}</p>}
            <input
              type="tel"
              placeholder="Телефон"
              value={numberTelephone}
              onChange={handleNumberTelephoneChange}
              required
              className={styles.input}
            />
            {error && <p className={styles.error}>{error}</p>}
            <input
              type="email"
              placeholder="Email"
              // value={email}
              required
              className={styles.input}
            />

            <h2 className={styles.subtitle}>Адрес доставки</h2>
            <input
              type="text"
              placeholder="Город"
              required
              className={styles.input}
            />
            <input
              type="text"
              placeholder="Улица, дом, квартира"
              required
              className={styles.input}
            />
            <input
              type="text"
              placeholder="Комментарий к заказу"
              className={styles.input}
            />

            <div className={styles.payment}>
              <h2 className={styles.subtitle}>Способ оплаты</h2>
              <label className={styles.radioLabel}>
                <input type="radio" name="payment" defaultChecked /> Онлайн
              </label>
              <label className={styles.radioLabel}>
                <input type="radio" name="payment" /> При получении
              </label>
            </div>

            <button type="submit" className={styles.button}>
              Оформить заказ
            </button>
          </form>
        </div>

        {/* Корзина */}
        <div className={styles.summary}>
          <h2 className={styles.subtitle}>Ваш заказ:</h2>

          {basket.map((el) => {
            return (
              <div key={el.id} className={styles.item}>
                <span>{el.title}</span>
              </div>
            );
          })}

          <hr />
          <div className={styles.total}>
            <strong>Итого:</strong>
            <strong>{totalPrice}</strong>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Payment;
